/** Live peer-use discovery augments, and never replaces, the frozen use roster. */
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {execFileSync} from 'node:child_process';
import {createRequire} from 'node:module';
import {lstatSync, readFileSync} from 'node:fs';
import {dirname, join, resolve} from 'node:path';
import {fileURLToPath} from 'node:url';
import {authoredUseInventory, authoredUseReviewEvidence} from './authored-use-inventory.mjs';

const ts = createRequire(import.meta.url)('typescript');
const defaultRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const productPrefix = 'projects/ngx-material-legacy/';
const hash = bytes => createHash('sha256').update(bytes).digest('hex');
const key = row => JSON.stringify([row?.file, row?.module, row?.symbol]);
const compare = (a, b) => a < b ? -1 : a > b ? 1 : 0;

function safePath(path) {
  assert.equal(typeof path, 'string');
  assert.ok(path.startsWith(productPrefix) && path.endsWith('.ts') && !path.endsWith('.spec.ts'));
  assert.ok(!path.includes('\\') && path.split('/').every(part => part && part !== '.' && part !== '..'));
}

/** Named imports/reexports plus namespace, default, side-effect and import-type routes.
 * A computed dynamic import is an unresolved route, rather than a silent omission.
 * Specs have their separate historical gate; production testing harnesses are included.
 */
export function scanCurrentAuthoredUses({root = defaultRoot, files, readSource} = {}) {
  const paths = files ?? execFileSync('rg', ['--files', '--hidden', '--no-ignore',
    productPrefix.slice(0, -1), '--glob', '*.ts', '--glob', '!*.spec.ts'],
    {cwd: root, encoding: 'utf8'}).trim().split('\n').filter(Boolean);
  assert.ok(paths.length, 'empty current authored source population');
  assert.equal(new Set(paths).size, paths.length, 'duplicate authored source path');
  const sources = [], uses = new Map();
  for (const path of [...paths].sort(compare)) {
    safePath(path);
    if (!readSource) {
      let member = root;
      for (const part of path.split('/')) {
        member = join(member, part);
        assert.ok(!lstatSync(member).isSymbolicLink(), 'symlink in authored source route');
      }
      assert.ok(lstatSync(member).isFile());
    }
    const bytes = readSource ? readSource(path) : readFileSync(join(root, path));
    assert.ok(typeof bytes === 'string' || Buffer.isBuffer(bytes));
    const text = bytes.toString(), source = ts.createSourceFile(path, text, ts.ScriptTarget.Latest, true);
    assert.equal(source.parseDiagnostics.length, 0, 'unparsed authored source ' + path);
    const digest = hash(bytes), file = path.slice(productPrefix.length);
    sources.push({path, sha256: digest});
    const add = (module, symbol, node, kind, localName = null, typeOnly = false) => {
      const row = {file, module, symbol};
      const id = key(row);
      if (!uses.has(id)) uses.set(id, {...row, candidate_source_sha256: digest, occurrences: []});
      uses.get(id).occurrences.push({kind, local_name: localName, type_only: typeOnly,
        line: source.getLineAndCharacterOfPosition(node.getStart(source)).line + 1});
    };
    const peer = spec => typeof spec === 'string' && spec.startsWith('@angular/');
    for (const node of source.statements) {
      if (ts.isImportDeclaration(node) && ts.isStringLiteral(node.moduleSpecifier) && peer(node.moduleSpecifier.text)) {
        const module = node.moduleSpecifier.text, clause = node.importClause;
        if (!clause) add(module, '<side-effect>', node, 'side-effect-import');
        else {
          if (clause.name) add(module, 'default', clause.name, 'default-import', clause.name.text, clause.isTypeOnly);
          const bindings = clause.namedBindings;
          if (bindings && ts.isNamedImports(bindings)) for (const item of bindings.elements)
            add(module, (item.propertyName || item.name).text, item, 'named-import', item.name.text,
              clause.isTypeOnly || item.isTypeOnly);
          else if (bindings && ts.isNamespaceImport(bindings))
            add(module, '*', bindings, 'namespace-import', bindings.name.text, clause.isTypeOnly);
        }
      } else if (ts.isExportDeclaration(node) && node.moduleSpecifier &&
          ts.isStringLiteral(node.moduleSpecifier) && peer(node.moduleSpecifier.text)) {
        const module = node.moduleSpecifier.text, clause = node.exportClause;
        if (clause && ts.isNamedExports(clause)) for (const item of clause.elements)
          add(module, (item.propertyName || item.name).text, item, 'named-reexport', item.name.text,
            node.isTypeOnly || item.isTypeOnly);
        else add(module, '*', node, 'namespace-reexport', clause?.name?.text ?? null, node.isTypeOnly);
      } else if (ts.isImportEqualsDeclaration(node) && ts.isExternalModuleReference(node.moduleReference)) {
        const spec = node.moduleReference.expression;
        if (spec && ts.isStringLiteral(spec) && peer(spec.text))
          add(spec.text, '*', node, 'import-equals', node.name.text, node.isTypeOnly);
      }
    }
    const visit = node => {
      if (ts.isImportTypeNode(node) && ts.isLiteralTypeNode(node.argument) &&
          ts.isStringLiteral(node.argument.literal) && peer(node.argument.literal.text)) {
        const symbol = node.qualifier ? node.qualifier.getText(source).split('.')[0] : '*';
        add(node.argument.literal.text, symbol, node, 'import-type', null, true);
      }
      if (ts.isCallExpression(node) && node.expression.kind === ts.SyntaxKind.ImportKeyword) {
        const spec = node.arguments[0];
        if (spec && (ts.isStringLiteral(spec) || ts.isNoSubstitutionTemplateLiteral(spec))) {
          if (peer(spec.text)) add(spec.text, '*', node, 'dynamic-import');
        } else add('<computed-module>', '<unresolved>', node, 'computed-dynamic-import');
      }
      ts.forEachChild(node, visit);
    };
    visit(source);
  }
  const symbolUses = [...uses.values()].sort((a, b) => compare(key(a), key(b)));
  return {schema_version: 1, compiler: ts.version, source_files: sources,
    source_population_sha256: hash(JSON.stringify(sources)), symbol_uses: symbolUses};
}

/** Review new routes with the same per-caller evidence rules as frozen routes.
 * Removed seed uses remain obligations of the frozen ledger, never automatic passes.
 */
export function currentAuthoredUseAdmission({current, frozen, candidate, line, readMember}) {
  const frozenKeys = new Set(frozen.map(key));
  const currentKeys = new Set(current.symbol_uses.map(key));
  const additions = current.symbol_uses.filter(row => !frozenKeys.has(key(row)));
  const removed = frozen.filter(row => !currentKeys.has(key(row)));
  const scopeValid = candidate?.schema_version === 1 && candidate?.line === line &&
    ['in-progress', 'closed'].includes(candidate?.status);
  const wanted = new Map(additions.map(row => [key(row), row]));
  const snapshotValid = candidate?.current_source_population_sha256 === current.source_population_sha256 &&
    candidate?.current_uses === current.symbol_uses.length &&
    candidate?.current_source_files === current.source_files.length &&
    candidate?.symbol_use_count === additions.length && Array.isArray(candidate?.symbol_uses) &&
    candidate.symbol_uses.every(row => {
      const actual = wanted.get(key(row));
      return actual && row.candidate_source_sha256 === actual.candidate_source_sha256 &&
        JSON.stringify(row.occurrences) === JSON.stringify(actual.occurrences);
    });
  const inventory = authoredUseInventory(additions, candidate);
  const reviews = inventory.invalid ? {reviewed: 0, insufficient: inventory.invalid, insufficient_uses: []}
    : authoredUseReviewEvidence(candidate, line, readMember, hash);
  const ready = scopeValid && snapshotValid && inventory.complete && inventory.open === 0 &&
    candidate.status === 'closed' && reviews.insufficient === 0;
  return {ready, scope_valid: scopeValid, source_snapshot_valid: snapshotValid,
    current_uses: current.symbol_uses.length,
    current_source_files: current.source_files.length,
    current_source_population_sha256: current.source_population_sha256,
    additional_uses: additions.length, removed_seed_uses: removed.length,
    inventory, review_evidence: reviews};
}

#!/usr/bin/env node
/**
 * Chromium PR-slice for legacy control families: input, list, slider, radio,
 * checkbox, and slide-toggle.
 *
 * Asserts honest family/state cells: input default+focused, list/slider/radio/
 * checkbox/slide-toggle default+disabled. Supports --zoneless (no Zone.js;
 * provideZoneless ChangeDetection). Does not fan success into unexecuted
 * engines or states. Does not claim G10.
 *
 *   node scripts/browser-control-families.mjs --tarball <path>
 *   node scripts/browser-control-families.mjs --tarball <path> --zoneless
 */
import {npmToolingOptions} from './npm-tooling-options.mjs';
import {createHash} from 'node:crypto';
import {observeComponentHighContrast,componentHighContrastOkay} from './component-high-contrast-contract.mjs';
import {announcedChromeEndpoint,debuggerMatchesChild} from './chromium-debug-endpoint.mjs';
import {spawnSync as __spawnSyncForWs} from 'node:child_process';
if (typeof globalThis.WebSocket !== 'function') {
  // Local Node 20 shells need the experimental flag; CI/Chainman Node 22+ has WebSocket.
  const relaunch = __spawnSyncForWs(process.execPath, ['--experimental-websocket', ...process.argv.slice(1)], {
    stdio: 'inherit',
    env: process.env,
  });
  process.exit(relaunch.status ?? 1);
}

import {spawn, spawnSync} from 'node:child_process';
import {createRequire} from 'node:module';
import {createServer} from 'node:http';
import {existsSync, mkdtempSync, mkdirSync, readFileSync, realpathSync, writeFileSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {dirname, join, relative, resolve} from 'node:path';
import {fileURLToPath} from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
let reportPath = join(root, 'compatibility/rc/reports/browser-control-families.json');
const esbuild = createRequire(join(root, 'package.json'))('esbuild');

function fail(code, message) {
  console.error(message);
  process.exit(code);
}

let tarball = null;
let zoneless = false;
for (let i = 2; i < process.argv.length; i += 1) {
  if (process.argv[i] === '--zoneless') {
    zoneless = true;
    reportPath = join(root, 'compatibility/rc/reports/browser-control-families-zoneless.json');
    continue;
  }
  if (process.argv[i] === '--tarball') {
    const value = process.argv[i + 1];
    if (!value || value.startsWith('-')) fail(2, '--tarball requires a path');
    tarball = resolve(value);
    i += 1;
    continue;
  }
  fail(2, `Unknown argument: ${process.argv[i]}`);
}
if (!tarball) fail(2, '--tarball is required');

function resolveChromeBin() {
  if (process.env.CHROME_BIN && existsSync(process.env.CHROME_BIN)) return process.env.CHROME_BIN;
  for (const candidate of [
    '/usr/bin/google-chrome',
    '/usr/bin/google-chrome-stable',
    '/usr/bin/chromium-browser',
    '/usr/bin/chromium',
    '/snap/bin/chromium',
  ]) {
    if (existsSync(candidate)) return candidate;
  }
  fail(1, 'No Chrome/Chromium binary found; set CHROME_BIN');
}
const chromeBin = resolveChromeBin();

const consumer = mkdtempSync(join(tmpdir(), 'ngx-compat-control-families-'));
const installTarball = join(consumer, 'library.tgz');
writeFileSync(installTarball, readFileSync(tarball));
writeFileSync(join(consumer, 'package.json'), JSON.stringify({
  name: 'ngx-compat-control-families-browser',
  private: true,
  dependencies: {
    '@angular/animations': '22.1.7',
    '@angular/cdk': '22.1.7',
    '@angular/common': '22.1.7',
    '@angular/compiler': '22.1.7',
    '@angular/compiler-cli': '22.1.7',
    '@angular/core': '22.1.7',
    '@angular/forms': '22.1.7',
    '@angular/material': '22.1.7',
    '@angular/platform-browser': '22.1.7',
    '@angular/platform-browser-dynamic': '22.1.7',
    '@ngx-compat/material-legacy': `file:${installTarball}`,
    rxjs: '7.8.2',
    tslib: '2.8.1',
    typescript: '6.0.3',
    ...(zoneless ? {} : {'zone.js': '0.16.3'}),
  },
}, null, 2));
writeFileSync(join(consumer, '.npmrc'), 'install-links=true\nfund=false\naudit=false\n');
const env = {...process.env, NODE_OPTIONS: ''};
delete env.NODE_PATH;
const install = spawnSync('npm', ['install', '--ignore-scripts', '--no-audit', '--no-fund', '--package-lock'], npmToolingOptions({
  cwd: consumer, encoding: 'utf8', timeout: 180000, env,
}, ['install', '--ignore-scripts', '--no-audit', '--no-fund', '--package-lock']));
if (install.status !== 0) fail(1, (install.stderr || install.stdout || 'npm install failed').slice(-2000));
const installed = realpathSync(join(consumer, 'node_modules/@ngx-compat/material-legacy'));
if (relative(realpathSync(consumer), installed).startsWith('..')) fail(1, `Library resolved outside the consumer: ${installed}`);

mkdirSync(join(consumer, 'src'), {recursive: true});
writeFileSync(join(consumer, 'src/main.ts'), `${zoneless ? '' : `import 'zone.js';
`}import {Component, NgModule${zoneless ? ', provideZonelessChangeDetection' : ''}} from '@angular/core';
import {BrowserModule} from '@angular/platform-browser';
import {platformBrowserDynamic} from '@angular/platform-browser-dynamic';
import {FormsModule} from '@angular/forms';
import {MATERIAL_ANIMATIONS} from '@angular/material/core';
import {MatLegacyFormFieldModule} from '@ngx-compat/material-legacy/legacy-form-field';
import {MatLegacyInputModule} from '@ngx-compat/material-legacy/legacy-input';
import {MatLegacyListModule} from '@ngx-compat/material-legacy/legacy-list';
import {MatLegacySliderModule} from '@ngx-compat/material-legacy/legacy-slider';
import {MatLegacyRadioModule} from '@ngx-compat/material-legacy/legacy-radio';
import {MatLegacyCheckboxModule} from '@ngx-compat/material-legacy/legacy-checkbox';
import {MatLegacySlideToggleModule} from '@ngx-compat/material-legacy/legacy-slide-toggle';

@Component({
  standalone: false,
  selector: 'lab-root',
  template: \`
    <mat-form-field id="input-ff" appearance="fill">
      <mat-label>Label</mat-label>
      <input id="plain-input" matInput [(ngModel)]="text" placeholder="Type here">
    </mat-form-field>

    <mat-list id="plain-list">
      <mat-list-item id="list-item-a">Alpha</mat-list-item>
      <mat-list-item id="list-item-disabled" [disabled]="true">Disabled</mat-list-item>
    </mat-list>

    <mat-slider id="slider-default" [(ngModel)]="value" min="0" max="100" step="1" thumbLabel></mat-slider>
    <mat-slider id="slider-disabled" [disabled]="true" [value]="25" min="0" max="100"></mat-slider>

    <mat-radio-group id="radio-group-default" [(ngModel)]="radioValue">
      <mat-radio-button id="radio-a" value="a">Alpha</mat-radio-button>
      <mat-radio-button id="radio-b" value="b">Beta</mat-radio-button>
    </mat-radio-group>
    <mat-radio-group id="radio-group-disabled" [disabled]="true" [(ngModel)]="radioDisabledValue">
      <mat-radio-button id="radio-disabled" value="x">Disabled</mat-radio-button>
    </mat-radio-group>

    <mat-checkbox id="checkbox-default" [(ngModel)]="checked">Default</mat-checkbox>
    <mat-checkbox id="checkbox-disabled" [disabled]="true">Disabled</mat-checkbox>

    <mat-slide-toggle id="toggle-default" [(ngModel)]="toggled">Default</mat-slide-toggle>
    <mat-slide-toggle id="toggle-disabled" [disabled]="true">Disabled</mat-slide-toggle>
  \`,
})
export class LabRoot {
  text = '';
  value = 40;
  radioValue = 'a';
  radioDisabledValue = 'x';
  checked = false;
  toggled = false;
}

@NgModule({
  imports: [
    BrowserModule,
    FormsModule,
    MatLegacyFormFieldModule,
    MatLegacyInputModule,
    MatLegacyListModule,
