@Component({
  standalone: false,
  selector: 'lab-root',
  template: ${JSON.stringify(labHtml())},
})
export class LabRoot {
  readonly rippleOnly = typeof window !== 'undefined' && new URL(window.location.href).searchParams.get('legacyRippleOnly') === '1';
  private dialog = inject(MatLegacyDialog);
  private snack = inject(MatLegacySnackBar);
  cspOnly = typeof window !== 'undefined' && !!(window as unknown as {__cspOnly?: boolean}).__cspOnly;
  matcher = new LabMatcher();
  forceSliderInvalid = false;
  sliderValue = 20;
  readonly autoSelection = signal<string | null>(null);
  readonly chipControl = new FormControl<string | null>(null);
  readonly tipMessage = signal('Hello tip');
  readonly outlineVisible = signal(true);
  readonly outlinePrefix = signal(false);
  readonly outlineDirection = signal<'ltr' | 'rtl'>('ltr');
  readonly paginationEpoch = signal(0);
  readonly paginationLabels = ['Pagination 0', 'Pagination 1', 'Pagination 2', 'Pagination 3', 'Pagination 4', 'Pagination 5'];
  cols = ['name'];
  rows = [{name: 'Ada'}];
  @ViewChild('menuTrigger') menuTrigger!: any;
  @ViewChild('autoTrigger') autoTrigger!: any;
  @ViewChild('tip') tip!: any;
  @ViewChild('tipOff') tipOff!: any;
  @ViewChild('chipList') chipList?: MatLegacyChipList;
  @ViewChild(TooltipAriaLifetimeLab) ariaLifetimeLab?: TooltipAriaLifetimeLab;
  @ViewChild(RippleDelegationLab) rippleDelegationLab?: RippleDelegationLab;
  @ViewChild(RippleDelegationFrameLab) rippleFrameLab?: RippleDelegationFrameLab;
  @ViewChild(CheckboxTimerLifetimeLab) checkboxTimerLifetimeLab?: CheckboxTimerLifetimeLab;
  @ViewChild(FormFieldDirectionLifetimeLab) fieldDirectionLifetimeLab?: FormFieldDirectionLifetimeLab;
  @ViewChild(SnackAnnouncementLifetimeLab) snackAnnouncementLifetimeLab?: SnackAnnouncementLifetimeLab;
  @ViewChildren(MatLegacyInput) inputs!: QueryList<MatLegacyInput>;
  @ViewChildren(MatLegacySelect) selects!: QueryList<MatLegacySelect>;
  @ViewChildren(MatLegacyChipList) chipLists!: QueryList<MatLegacyChipList>;
  @ViewChildren(MatLegacySelect, {read: ChangeDetectorRef}) selectDetectors!: QueryList<ChangeDetectorRef>;
  @ViewChildren(MatLegacyChipList, {read: ChangeDetectorRef}) chipDetectors!: QueryList<ChangeDetectorRef>;
  @ViewChildren(MatLegacyFormField, {read: ChangeDetectorRef}) fieldDetectors!: QueryList<ChangeDetectorRef>;
  openDialog(): void { this.dialog.open(DialogBody); }
  openMenu(): void { this.menuTrigger.openMenu(); }
  openSnack(): void { this.snack.open('Saved', 'OK'); }
  markInvalid(): void {
    this.matcher.on = true;
    this.inputs.forEach(input => input.updateErrorState());
    this.selects.forEach(select => select.updateErrorState());
    this.chipLists.forEach(list => list.updateErrorState());
    this.selectDetectors.forEach(detector => detector.markForCheck());
    this.chipDetectors.forEach(detector => detector.markForCheck());
    this.fieldDetectors.forEach(detector => detector.markForCheck());
  }
  ngAfterViewInit(): void {
    const lab = this;
    (window as unknown as {__lab: unknown}).__lab = {
      closeTransient() {
        lab.rippleFrameLab?.dispose();
        try { lab.dialog.closeAll(); } catch { /* overlay already gone */ }
        try { lab.snack.dismiss(); } catch { /* snack already gone */ }
        try { lab.menuTrigger && lab.menuTrigger.closeMenu(); } catch { /* menu already closed */ }
        try { lab.autoTrigger && lab.autoTrigger.closePanel(); } catch { /* panel already closed */ }
        try { lab.tip && lab.tip.hide(0); } catch { /* tooltip already hidden */ }
        lab.matcher.on = false;
        lab.forceSliderInvalid = false;
        lab.autoSelection.set(null);
        lab.tipMessage.set('Hello tip');
        lab.paginationEpoch.update(value => value + 1);
        lab.outlineVisible.set(true); lab.outlinePrefix.set(false); lab.outlineDirection.set('ltr');
      },
      openDialog() { lab.openDialog(); },
      openMenu() { lab.openMenu(); },
      openSnack() { lab.openSnack(); },
      runTooltipAriaLifetime() {
        if (!lab.ariaLifetimeLab) return Promise.reject(new Error('tooltip ARIA fixture missing'));
        return lab.ariaLifetimeLab.run();
      },
      prepareRippleDelegation() {
        if (!lab.rippleOnly || !lab.rippleDelegationLab) return Promise.reject(new Error('ripple-only child unavailable'));
        return lab.rippleDelegationLab.prepare();
      },
      finishRippleDelegation() {
        if (!lab.rippleDelegationLab) return Promise.reject(new Error('ripple child unavailable'));
        return lab.rippleDelegationLab.finish();
      },
      disposeRippleDelegation() {lab.rippleDelegationLab?.dispose();},
      rippleDelegationTarget() {
        if (!lab.rippleDelegationLab) throw new Error('ripple child unavailable');
        return lab.rippleDelegationLab.target();
      },
      prepareRippleFrame() {
        if (lab.rippleOnly || !lab.rippleFrameLab) return Promise.reject(new Error('ripple parent unavailable'));
        return lab.rippleFrameLab.prepare();
      },
      disposeRippleFrame() {lab.rippleFrameLab?.dispose();},
      scrollRippleFrame() {lab.rippleFrameLab?.scrollIntoView();},
      rippleFrameTargetBox() {return lab.rippleFrameLab?.targetBox();},
      finishRippleFrame() {
        if (!lab.rippleFrameLab) return Promise.reject(new Error('ripple parent unavailable'));
        return lab.rippleFrameLab.finish();
      },
      runCheckboxTimerLifetime() {
        if (!lab.checkboxTimerLifetimeLab) return Promise.reject(new Error('checkbox timer fixture missing'));
        return lab.checkboxTimerLifetimeLab.run();
      },
      runFormFieldDirectionLifetime() {
        if (!lab.fieldDirectionLifetimeLab) return Promise.reject(new Error('field direction fixture missing'));
        return lab.fieldDirectionLifetimeLab.run();
      },
      runSnackAnnouncementLifetime() {
        if (!lab.snackAnnouncementLifetimeLab) return Promise.reject(new Error('snack announcement fixture missing'));
        return lab.snackAnnouncementLifetimeLab.run();
      },
      readAutocompleteSelection() { return lab.autoSelection(); },
      readChipFormState() { return {focused: lab.chipList?.focused, touched: lab.chipControl.touched}; },
      resetChipFormState() { lab.chipControl.markAsUntouched(); },
      matcher: lab.matcher,
      setSliderFlag(on: boolean) { lab.forceSliderInvalid = on; },
      selectSecondTab() {
        const label = document.querySelectorAll('#wrap-tabs .mat-tab-label')[1] as HTMLElement | undefined;
        if (label) label.click();
      },

    };
    document.documentElement.dataset.labReady = '1';
  }
}

