  const scope = {abs, sf, functions, imports};
  cache.set(abs, scope);
  return scope;
}

function walkFunctionBody(fn, suite, scope, cases, cache, stack, sharedPath) {
  if (!fn) return;
  if (ts.isArrowFunction(fn) && !ts.isBlock(fn.body)) {
    walkNode(fn.body, suite, scope, cases, cache, stack, sharedPath);
    return;
  }
  const body = fn.body;
  if (body) walkNode(body, suite, scope, cases, cache, stack, sharedPath);
}

function resolveCall(expr, scope, cache) {
  if (!ts.isIdentifier(expr)) return null;
  if (scope.functions.has(expr.text)) {
    return {fn: scope.functions.get(expr.text), scope, shared: null};
  }
  const imported = scope.imports.get(expr.text);
  if (!imported) return null;
  const other = loadScope(imported.file, cache);
  const fn = other.functions.get(imported.exportName);
  if (!fn) return null;
  return {fn, scope: other, shared: path.relative(root, imported.file).split(path.sep).join('/')};
}

function walkBlock(node, suite, scope, cases, cache, stack, sharedPath) {
  const functions = new Map(scope.functions);
  for (const statement of node.statements) {
    if (ts.isFunctionDeclaration(statement) && statement.name && statement.body) {
      functions.set(statement.name.text, statement);
    }
  }
  const localScope = {...scope, functions};
  for (const statement of node.statements) {
    walkNode(statement, suite, localScope, cases, cache, stack, sharedPath);
  }
}

function walkNode(node, suite, scope, cases, cache, stack, sharedPath) {
  if (ts.isBlock(node) || ts.isSourceFile(node)) {
    walkBlock(node, suite, scope, cases, cache, stack, sharedPath);
    return;
  }
  if (ts.isCallExpression(node)) {
    const kind = jasmineKind(node.expression);
    if (kind === 'describe' || kind === 'fdescribe' || kind === 'xdescribe') {
      const title = staticString(node.arguments[0]);
      const callback = node.arguments[1];
      if (title == null || !callback) {
        throw new Error(`non-static describe in ${path.relative(root, scope.abs)}`);
      }
      walkFunctionBody(callback, [...suite, title], scope, cases, cache, stack, sharedPath);
      return;
    }
    if (kind === 'it' || kind === 'fit' || kind === 'xit' || kind === 'test') {
      const title = staticString(node.arguments[0]);
      if (title == null) throw new Error(`non-static it in ${path.relative(root, scope.abs)}`);
      cases.push({
        suite: [...suite],
        description: title,
        shared: sharedPath,
      });
      return;
    }
    const target = resolveCall(node.expression, scope, cache);
    if (target) {
      const key = `${target.scope.abs}::${ts.isIdentifier(node.expression) ? node.expression.text : kind || ''}`;
      if (!stack.includes(key)) {
        walkFunctionBody(target.fn, suite, target.scope, cases, cache, [...stack, key], target.shared || sharedPath);
      }
      return;
    }
  }
  if (
    ts.isFunctionDeclaration(node) ||
    ts.isFunctionExpression(node) ||
    ts.isArrowFunction(node) ||
    ts.isMethodDeclaration(node) ||
    ts.isClassDeclaration(node) ||
    ts.isClassExpression(node)
  ) {
    return;
  }
  ts.forEachChild(node, child => walkNode(child, suite, scope, cases, cache, stack, sharedPath));
}

export function fullNameOf(testCase) {
  return testCase.suite.length ? `${testCase.suite.join(' > ')} > ${testCase.description}` : testCase.description;
}

export function deriveHistoricalRoster(repoRoot = root) {
  const inventory = JSON.parse(
    fs.readFileSync(path.join(repoRoot, 'testing/legacy-runner/historical-inventory.json'), 'utf8'),
  );
  const specs = JSON.parse(
    fs.readFileSync(path.join(repoRoot, 'testing/legacy-runner/historical-specs.json'), 'utf8'),
  );
  if (!Array.isArray(inventory.rows) || inventory.rows.length !== 57) {
    throw new Error(`historical inventory denominator is ${inventory.rows?.length}, expected 57`);
  }
  if (specs.length !== 57) throw new Error(`historical-specs.json has ${specs.length} rows, expected 57`);
  const byCandidate = new Map(inventory.rows.map(row => [row.candidate, row]));
  const cache = new Map();
  const cases = [];
  for (const spec of specs) {
    const row = byCandidate.get(spec.candidate);
    if (!row) throw new Error(`spec ${spec.candidate} is not in the inventory`);
    const abs = path.join(repoRoot, spec.candidate);
    const scope = loadScope(abs, cache);
    const found = [];
    walkNode(scope.sf, [], scope, found, cache, [], null);
    found.forEach((testCase, index) => {
      const fullName = fullNameOf(testCase);
      cases.push({
        case_id: `historical-legacy-artifact/original-and-shared-cases/${row.historical_path}#${index}`,
        historical_path: row.historical_path,
        candidate: row.candidate,
        adaptation: row.adaptation,
        shared: testCase.shared,
        full_name: fullName,
        index,
        kind: testCase.shared ? 'shared' : 'direct',
      });
    });
  }
  for (const row of inventory.rows) {
    if (cases.some(testCase => testCase.historical_path === row.historical_path && testCase.kind !== 'shared-export')) continue;
    const caller = cases.find(testCase => testCase.shared === row.candidate);
    if (!caller) throw new Error(`historical path has no direct or shared cases: ${row.historical_path}`);
    cases.push({
      case_id: `historical-legacy-artifact/original-and-shared-cases/${row.historical_path}#shared-export`,
      historical_path: row.historical_path,
      candidate: row.candidate,
      adaptation: row.adaptation,
      shared: null,
      full_name: null,
      index: null,
      kind: 'shared-export',
      called_from: caller.historical_path,
    });
  }
  const ids = cases.map(testCase => testCase.case_id);
  if (new Set(ids).size !== ids.length) throw new Error('derived historical case ids are not unique');
  const paths = inventory.rows.map(row => row.historical_path);
  return {
    cases,
    ids,
    paths,
    discovery_negative_ids: [...DISCOVERY_NEGATIVE_IDS],
    shared_cases: cases.filter(testCase => testCase.shared).length,
    direct_cases: cases.filter(testCase => !testCase.shared).length,
  };
}

function componentSpecs(executed) {
  return (executed || []).filter(spec => spec && typeof spec.full_name === 'string' && !isRunnerControl(spec.full_name));
}

/**
 * Returns a list of rejection reasons. Empty means the observation matches the
 * derived roster on a clean artifact-bound run. Aggregate totals are ignored
 * except to recognize an aggregate-only payload.
 */
export function rejectionReasons(roster, executed, context) {
  const reasons = [];
  if (!context || context.source_clean !== true) reasons.push('dirty-source');
  const artifactBound = context &&
    context.subject_mode === 'artifact' &&
    typeof context.artifact_sha256 === 'string' &&
    context.artifact_sha256.length === 64 &&
    context.artifact_sha256 === context.library_sha256;
  if (!artifactBound) reasons.push('unbound-artifact');
  const specs = componentSpecs(executed);
  const specCases = roster.cases.filter(testCase => testCase.kind !== 'shared-export');
  const exportCases = roster.cases.filter(testCase => testCase.kind === 'shared-export');
  const aggregate = Number(context?.aggregate_executed || 0);
  if (specs.length === 0 && aggregate > 0) reasons.push('aggregate-only-success');
  const known = new Set(specCases.map(testCase => testCase.full_name));
  if (specs.some(spec => !known.has(spec.full_name))) reasons.push('forged-id');
  const mapped = new Set(context?.mapped_paths || []);
  const orderMismatch = specs.length !== specCases.length || specs.some((spec, index) =>
    spec.full_name !== specCases[index]?.full_name || spec.success !== true || spec.skipped === true);
  const exportMismatch = exportCases.some(testCase => !specCases.some(specCase =>
    specCase.shared === testCase.candidate && specs.some(spec => spec.full_name === specCase.full_name && spec.success === true)));
  const missingPath = roster.paths.some(historicalPath => !mapped.has(historicalPath)) || orderMismatch || exportMismatch;
  if (missingPath) reasons.push('missing-path');
  return [...new Set(reasons)];
}

export function positiveMatches(roster, executed, context) {
  return rejectionReasons(roster, executed, context).length === 0;
}

const NEGATIVE_CODE = {
  'historical-legacy-artifact/discovery-negatives/missing-path': 'missing-path',
  'historical-legacy-artifact/discovery-negatives/forged-id': 'forged-id',
  'historical-legacy-artifact/discovery-negatives/aggregate-only-success': 'aggregate-only-success',
  'historical-legacy-artifact/discovery-negatives/dirty-source': 'dirty-source',
  'historical-legacy-artifact/discovery-negatives/unbound-artifact': 'unbound-artifact',
};

function goodContext(roster, executed, context) {
  return {
    source_clean: true,
    subject_mode: 'artifact',
    artifact_sha256: context.library_sha256,
    library_sha256: context.library_sha256,
    aggregate_executed: executed.length,
    mapped_paths: roster.paths,
  };
}

/**
 * Run the real binder against one mutated observation per negative. A pass
 * means that mutation was rejected. A binder that accepts everything fails.
 */
export function discoveryNegativeResults(roster, executed, context) {
  const specs = componentSpecs(executed);
  const base = goodContext(roster, specs, context);
  const probes = {
    'missing-path': [roster, specs.slice(1), base],
    'forged-id': [roster, [...specs, {full_name: 'forged historical case that is not in the roster', success: true, skipped: false}], base],
    'aggregate-only-success': [roster, [], {...base, aggregate_executed: Number(context.aggregate_executed || specs.length)}],
    'dirty-source': [roster, specs, {...base, source_clean: false}],
    'unbound-artifact': [roster, specs, {...base, subject_mode: 'workspace-dist', artifact_sha256: null}],
  };
  return DISCOVERY_NEGATIVE_IDS.map(caseId => {
    const code = NEGATIVE_CODE[caseId];
    const reasons = rejectionReasons(...probes[code]);
    const rejected = reasons.includes(code);
    return {
      case_id: caseId,
      result: rejected ? 'pass' : 'fail',
      rejection: code,
      observed_reasons: reasons,
    };
  });
}

#!/usr/bin/env node
/**
 * Coordinator path for native-motion. Derives the 21.x roster before launching
 * browsers, then binds observations to the packed artifact. WebKitGTK is the
 * webkit engine, not Safari. Does not claim G04 or G10.
 */
import {existsSync, lstatSync, mkdirSync, readFileSync, writeFileSync} from 'node:fs';
import {spawnSync} from 'node:child_process';
import {createHash} from 'node:crypto';
import {dirname, join, relative, resolve} from 'node:path';
import {fileURLToPath} from 'node:url';
import {resolveLibraryFromRun} from './resolve-run-library.mjs';
import {deriveMainRoster, observationProblems, SOURCE_LINE} from './native-motion-roster.mjs';
import {executeNativeMotion} from './native-motion-run.mjs';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');

function gitValue(args) {
  const result = spawnSync('git', args, {cwd: root, encoding: 'utf8'});
  return result.status === 0 ? result.stdout.trim() : '';
}

function coordinatorRequest() {
  const names = ['RC_CHECK_ID', 'RC_RUN_ID', 'RC_INVOCATION_ID', 'RC_EVIDENCE_BINDING', 'RC_ASSERTION_OUTPUT_DIR'];
  const present = names.filter(name => process.env[name]);
  if (present.length !== names.length) return {error: `incomplete coordinator environment: ${present.join(', ')}`};
  if (process.env.RC_CHECK_ID !== 'native-motion') return {error: 'RC_CHECK_ID is not native-motion'};
  const invocation = process.env.RC_INVOCATION_ID;
  if (!/^[A-Za-z0-9][A-Za-z0-9._-]{0,191}$/.test(invocation)) return {error: 'invalid invocation identity'};
  let binding;
  try { binding = JSON.parse(process.env.RC_EVIDENCE_BINDING); } catch { return {error: 'RC_EVIDENCE_BINDING is not JSON'}; }
  if (!binding || typeof binding !== 'object' || Array.isArray(binding)) return {error: 'binding is not an object'};
  if (binding.run_id !== process.env.RC_RUN_ID) return {error: 'binding run_id does not match RC_RUN_ID'};
  const outputDir = process.env.RC_ASSERTION_OUTPUT_DIR;
  if (!outputDir || !existsSync(outputDir)) return {error: 'assertion output directory is missing'};
  const stat = lstatSync(outputDir);
  if (!stat.isDirectory() || stat.isSymbolicLink()) return {error: 'assertion output directory is not a real directory'};
  if (!outputDir.endsWith(join('evidence', 'native-motion', invocation))) return {error: 'assertion directory is not check-owned'};
  return {binding, invocation, runId: process.env.RC_RUN_ID, outputDir, runDir: resolve(outputDir, '..', '..', '..'), line: binding.source_line};
}

function preflight() {
  const missing = [];
  const notes = [];
  const chrome = process.env.CHROME_BIN && existsSync(process.env.CHROME_BIN)
    ? process.env.CHROME_BIN
    : ['/usr/bin/chromium-browser', '/usr/bin/chromium', '/usr/bin/google-chrome'].find(path => existsSync(path));
  if (!chrome) missing.push('chromium');
  const firefox = process.env.FIREFOX_BIN && existsSync(process.env.FIREFOX_BIN) ? process.env.FIREFOX_BIN : (existsSync('/usr/bin/firefox') ? '/usr/bin/firefox' : '');
  if (!firefox) missing.push('firefox');
  else {
    const version = spawnSync(firefox, ['--version'], {encoding: 'utf8', timeout: 20000});
    notes.push((version.stdout || version.stderr || '').trim());
    if (version.status !== 0) missing.push('firefox');
  }
  if (!process.env.DISPLAY) missing.push('webkit');
  const probe = spawnSync('/usr/bin/python3', ['-c', 'import gi; gi.require_version("WebKit2", "4.1"); from gi.repository import WebKit2; print("%s.%s.%s" % (WebKit2.get_major_version(), WebKit2.get_minor_version(), WebKit2.get_micro_version()))'], {encoding: 'utf8', timeout: 30000});
  if (probe.status !== 0) {
    missing.push('webkit');
    notes.push((probe.stderr || probe.stdout || 'webkitgtk import failed').trim().slice(-400));
  } else notes.push(`webkitgtk ${probe.stdout.trim()}`);
  return {missing: [...new Set(missing)], notes, chrome, firefox};
}

export async function runAcceptance({runPath}) {
  const request = coordinatorRequest();
  const roster = deriveMainRoster();
  const matrix = JSON.parse(readFileSync(join(root, 'compatibility/rc/matrices/full-verify.json'), 'utf8'));
  const row = matrix.checks.find(item => item.check_id === 'native-motion');
  const matrixMismatch = JSON.stringify(row.acceptance.cases_by_line[SOURCE_LINE]) !== JSON.stringify(roster.groups)
    || Object.values(row.acceptance.cases_by_line.main).some(value => value !== null);
  const library = runPath ? resolveLibraryFromRun(runPath) : null;
  const artifactSha = library ? library.digest : '';
  const artifactBytes = library ? library.bytes : 0;
  const launch = preflight();
  let outcomes = [];
  let engines = {};
  let launchError = '';
  if (!matrixMismatch && request && !request.error && launch.missing.length === 0 && library && request.line === '21.x') {
    try {
      const executed = await executeNativeMotion(library.tarball);
      outcomes = executed.outcomes;
      engines = executed.engines;
    } catch (error) {
      launchError = error instanceof Error ? error.message : String(error);
    }
  }
  const observed = observationProblems({
    requiredIds: roster.ids,
    outcomes,
    engines,
    sourceClean: request && request.binding ? request.binding.source_clean === true : false,
    artifactSha,
    boundSha: artifactSha,
  });
  const commit = gitValue(['rev-parse', 'HEAD']);
  const tree = gitValue(['rev-parse', 'HEAD^{tree}']);
  const identity = [];
  if (!request || request.error) identity.push(request ? request.error : 'missing coordinator request');
  if (request && request.binding) {
    if (request.binding.source_clean !== true) identity.push('dirty source');
    if (request.binding.source_commit !== commit) identity.push('source commit mismatch');
    if (request.binding.source_tree !== tree) identity.push('source tree mismatch');
    if (request.line !== '21.x') identity.push('line is not 21.x');
  }
  if (matrixMismatch) identity.push('matrix roster is not the derived 21.x native-motion roster');
  if (launch.missing.length) identity.push(`missing browser ${launch.missing.join(', ')}`);
  if (launchError) identity.push(launchError);
  for (const [name, info] of Object.entries(engines)) {
    if (info && info.error) identity.push(`${name}: ${info.error}`);
  }
  const problems = [...identity, ...observed.problems.filter(item => !identity.includes(item))];
  const accepted = problems.length === 0 && observed.skipped.length === 0;
  const byId = new Map(outcomes.filter(item => item && item.ok === true).map(item => [item.id, item]));
  const evidenceById = new Map(outcomes.filter(item => item && item.id).map(item => [item.id, item.evidence || '']));
  if (!request || request.error) {
    console.error(problems.join('\n'));
    return 1;
  }
  const assertion = {
    kind: 'native-motion-observations',
    check_id: 'native-motion',
    run_id: request.runId,
    invocation_id: request.invocation,
    library_sha256: artifactSha,
    source_clean: request.binding.source_clean === true,
    webkit_backend: 'webkitgtk',
    safari_certification: false,
    engines,
    per_group: roster.perGroup,
    per_engine: roster.perEngine,
    not_applicable: roster.notApplicable,
    note: 'Cases were derived before the browsers launched. WebKitGTK is not Safari. detectChanges, a zero-duration stylesheet, a wrapper background, a missing engine, dirty source, and an unbound artifact are rejected. motion-smoke is a separate source check.',
    cases: roster.ids.map(id => ({
      case_id: id,
      result: byId.has(id) ? 'pass' : 'fail',
      evidence: evidenceById.get(id) || '',
    })),
  };
  const assertionPath = join(request.outputDir, 'motion-observations.json');
  const assertionBytes = Buffer.from(`${JSON.stringify(assertion)}\n`);
  writeFileSync(assertionPath, assertionBytes);
  const relativeAssertion = relative(request.runDir, assertionPath).split('\\').join('/');
  const output = {path: relativeAssertion, sha256: createHash('sha256').update(assertionBytes).digest('hex'), bytes: assertionBytes.length};
  const passedIds = roster.ids.filter(id => byId.has(id));
  const failedIds = roster.ids.filter(id => !byId.has(id));
  const report = {
    schema_version: 1,
    template: false,
    run_id: request.runId,
    check_id: 'native-motion',
    line: request.line,
    invocation_id: request.invocation,
    binding: request.binding,
    coverage: accepted ? 'complete' : 'incomplete',
    result: accepted ? 'pass' : 'fail',
    exit_code: accepted ? 0 : 1,
    subject_kind: 'artifact',
    subject_ids: ['library'],
    artifacts: {library: {sha256: artifactSha, bytes: artifactBytes}},
    expected_case_ids: roster.ids,
    discovered_case_ids: roster.ids,
    executed_case_ids: roster.ids,
    passed_case_ids: passedIds,
    failed_case_ids: accepted ? [] : failedIds.slice(0, 50),
    skipped_case_ids: [],
    unresolved_case_ids: [],
    exceptions: [],
    passed: passedIds.length,
    failed: accepted ? 0 : failedIds.length,
    skipped: 0,
    outputs: [output],
    case_results: roster.ids.map(id => ({
      case_id: id,
      result: byId.has(id) ? 'pass' : 'fail',
      kind: 'assertion',
      output_paths: [relativeAssertion],
    })),
    command: ['node', 'scripts/native-motion-acceptance.mjs', '--run', request.runId],
    limitations: accepted ? [
      'WebKit evidence is WebKitGTK WebKit2 4.1 with the process sandbox enabled, not Safari certification.',
      'Does not claim G04 or G10.',
      'Source motion-smoke is a separate check.',
    ] : problems.slice(0, 30),
    preflight: launch.notes,
  };
  mkdirSync(join(request.runDir, 'reports'), {recursive: true});
  writeFileSync(join(request.runDir, 'reports', 'native-motion.json'), `${JSON.stringify(report)}\n`);
  console.log(`native-motion: derived ${roster.ids.length} cases; accepted=${accepted}`);
  if (!accepted) {
    console.error(problems.slice(0, 30).join('\n'));
    if (observed.skipped.length) console.error(`skipped_count ${observed.skipped.length} first ${observed.skipped[0]}`);
  }
  return accepted ? 0 : 1;
}

const entry = process.argv[1] ? resolve(process.argv[1]) : '';
if (entry === fileURLToPath(import.meta.url)) {
  const runFlag = process.argv.indexOf('--run');
  const runPath = runFlag >= 0 ? process.argv[runFlag + 1] : '';
  if (!runPath) {
    console.error('--run is required');
    process.exit(1);
  }
  runAcceptance({runPath}).then(code => process.exit(code)).catch(err => {
    console.error(err);
    process.exit(1);
  });
}

