      <mat-tab-group [animationDuration]="tabDuration">
        <mat-tab label="One">One</mat-tab>
        <mat-tab label="Two">Two</mat-tab>
        <mat-tab label="Three">Three</mat-tab>
      </mat-tab-group>
      <button id="tip" type="button" #tip="matTooltip" matTooltip="Hello">Tip</button>
      <button *ngIf="showGone" id="tip-gone" type="button" #tipGone="matTooltip" matTooltip="Gone">Gone</button>
      </ng-container>
    </div>
  `,
})
export class MotionRoot {
  name = new FormControl('');
  tabDuration = '500ms';
  showGone = true;
  showSurfaces = false;
  @ViewChild(MatLegacyMenuTrigger) menuTrigger!: MatLegacyMenuTrigger;
  @ViewChild(MatLegacyMenu) menu!: MatLegacyMenu;
  @ViewChild(MatLegacySelect) select!: MatLegacySelect;
  @ViewChild(MatLegacyTabGroup) tabs!: MatLegacyTabGroup;
  @ViewChild('tip') tip!: MatLegacyTooltip;
  @ViewChild('tipGone') tipGone?: MatLegacyTooltip;

  constructor(
    private dialog: MatLegacyDialog,
    private snack: MatLegacySnackBar,
  ) {}

  ngAfterViewInit(): void {
    document.documentElement.dataset.labReady = '1';
  }

  probeDialog(): void { void this.guard('probe-dialog', () => this.measureDialog(false)); }
  probeDialogZero(): void { void this.guard('probe-dialog-zero', () => this.measureDialog(true)); }
  probeSnack(): void { void this.guard('probe-snack', () => this.measureSnack()); }
  probeMenu(): void { void this.guard('probe-menu', () => this.measureMenu()); }
  probeSelect(): void { void this.guard('probe-select', () => this.measureSelect()); }
  probeTooltip(): void { void this.guard('probe-tooltip', () => this.measureTooltip()); }
  probeTabs(): void { void this.guard('probe-tabs', () => this.measureTabs(false)); }
  probeTabsZero(): void { void this.guard('probe-tabs-zero', () => this.measureTabs(true)); }
  probeField(): void { void this.guard('probe-field', () => this.measureField()); }
  interruptDialogReversal(): void { void this.guard('interrupt-dialog-reversal', () => this.reversal()); }
  interruptDialogReopen(): void { void this.guard('interrupt-dialog-reopen', () => this.reopen()); }
  interruptDialogDestroy(): void { void this.guard('interrupt-dialog-destroy', () => this.destroyDialog()); }
  interruptSnack(): void { void this.guard('interrupt-snack', () => this.snackInterrupt()); }
  interruptMenuDuplicate(): void { void this.guard('interrupt-menu-duplicate', () => this.menuDuplicate()); }
  interruptMenuDescendant(): void { void this.guard('interrupt-menu-descendant', () => this.menuDescendant()); }
  interruptSelectDescendant(): void { void this.guard('interrupt-select-descendant', () => this.selectDescendant()); }
  interruptSelectFallback(): void { void this.guard('interrupt-select-fallback', () => this.selectFallback()); }
  interruptTooltip(): void { void this.guard('interrupt-tooltip-destroy', () => this.tooltipDestroy()); }
  interruptTabs(): void { void this.guard('interrupt-tabs', () => this.tabsRapid()); }

  private mode(): string {
    return new URLSearchParams(location.search).get('mode') || 'enabled';
  }

  private async guard(button: string, work: () => Promise<unknown>): Promise<void> {
    try {
      const value = await work();
      this.finish(button, value);
    } catch (err) {
      this.finish(button, {error: err instanceof Error ? err.message : String(err)});
    }
  }

  private finish(button: string, value: unknown): void {
    (window as unknown as {__step: unknown}).__step = value;
    document.documentElement.dataset.step = button;
    document.documentElement.dataset.stepState = 'done';
  }

  private wait(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  private async ensureSurfaces(): Promise<void> {
    if (!this.showSurfaces) {
      this.showSurfaces = true;
      await this.wait(60);
    }
    if (!this.menuTrigger || !this.select || !this.tabs || !this.tip) {
      throw new Error('motion surfaces were not constructed');
    }
  }

  private async waitFor(predicate: () => boolean, limit = 1200): Promise<void> {
    const started = Date.now();
    while (!predicate()) {
      if (Date.now() - started > limit) throw new Error('timed out waiting for motion');
      await this.wait(20);
    }
  }

  private duration(el: HTMLElement, property: 'transition-duration' | 'animation-duration'): number {
    const raw = getComputedStyle(el).getPropertyValue(property);
    let max = 0;
    for (const part of raw.split(',')) {
      const text = part.trim();
      if (text.endsWith('ms')) max = Math.max(max, parseFloat(text));
      else if (text.endsWith('s')) max = Math.max(max, parseFloat(text) * 1000);
    }
    return max < 1 ? 0 : max;
  }

  private visible(el: HTMLElement | null): boolean {
    if (!el) return false;
    const opacity = parseFloat(getComputedStyle(el).opacity);
    return Number.isFinite(opacity) && opacity > 0.85;
  }

  private async measureDialog(zero: boolean): Promise<unknown> {
    this.dialog.closeAll();
    let notifications = 0;
    const ref = this.dialog.open(DialogBody, zero ? {enterAnimationDuration: '0ms', exitAnimationDuration: '0ms'} : {});
    ref.afterOpened().subscribe(() => { notifications += 1; });
    await this.waitFor(() => !!document.querySelector('mat-dialog-container') && notifications >= 1);
    const el = document.querySelector('mat-dialog-container') as HTMLElement;
    const mode = zero ? 'zero' : this.mode();
    const observation = {
      selector: el.tagName === 'MAT-DIALOG-CONTAINER' ? 'mat-dialog-container' : '',
      selectorMatches: el.tagName === 'MAT-DIALOG-CONTAINER' && el.classList.contains('mat-dialog-container'),
      durationMs: this.duration(el, 'transition-duration'),
      finalState: this.visible(el) ? 'visible' : 'hidden',
      notifications,
      detectChangesCalls: 0,
    };
    ref.close();
    await this.wait(zero || mode !== 'enabled' ? 80 : 200);
    return {
      key: `dialog/${mode}`,
      observation,
      notify: {key: `dialog/afterOpened/${mode}`, observation: {notifications, detectChangesCalls: 0}},
    };
  }

  private async measureSnack(): Promise<unknown> {
    try { this.snack.dismiss(); } catch { /* none open */ }
    let notifications = 0;
    const ref = this.snack.open('Saved', 'OK', {duration: 30000});
    // Disabled motion next()+complete()s _onEnter inside open(), before this
    // subscribe. A Subject does not replay and complete() does not set closed,
    // so the only public signal of that single next is a synchronous complete.
    ref.afterOpened().subscribe({
      next: () => { notifications += 1; },
      complete: () => { if (notifications === 0) notifications = 1; },
    });
    await this.waitFor(() => {
      const el = document.querySelector('snack-bar-container');
      return !!el && notifications >= 1;
    }, 1500);
    const el = document.querySelector('snack-bar-container') as HTMLElement;
    const mode = this.mode();
    const observation = {
      selector: el.tagName === 'SNACK-BAR-CONTAINER' ? 'snack-bar-container' : '',
      selectorMatches: el.tagName === 'SNACK-BAR-CONTAINER' && el.classList.contains('mat-snack-bar-container'),
      durationMs: this.duration(el, 'animation-duration'),
      finalState: this.visible(el) ? 'visible' : 'hidden',
      notifications,
      detectChangesCalls: 0,
    };
    ref.dismiss();
    await this.wait(200);
    return {
      key: `snack-bar/${mode}`,
      observation,
      notify: {key: `snack-bar/afterOpened/${mode}`, observation: {notifications, detectChangesCalls: 0}},
    };
  }

  private async measureMenu(): Promise<unknown> {
    await this.ensureSurfaces();
    try { this.menuTrigger.closeMenu(); } catch { /* closed */ }
    let notifications = 0;
    this.menuTrigger.menuOpened.subscribe(() => { notifications += 1; });
    this.menuTrigger.openMenu();
    await this.waitFor(() => !!document.querySelector('.mat-menu-panel'));
    await this.wait(250);
    const el = document.querySelector('.mat-menu-panel') as HTMLElement;
    const mode = this.mode();
    const observation = {
      selector: el.classList.contains('mat-menu-panel') ? '.mat-menu-panel' : '',
      selectorMatches: el.classList.contains('mat-menu-panel') && !el.classList.contains('cdk-overlay-pane'),
      durationMs: this.duration(el, 'animation-duration'),
      finalState: this.visible(el) ? 'visible' : 'hidden',
      notifications,
      detectChangesCalls: 0,
    };
    this.menuTrigger.closeMenu();
    await this.wait(250);
    return {
      key: `menu/${mode}`,
      observation,
      notify: {key: `menu/menuOpened/${mode}`, observation: {notifications, detectChangesCalls: 0}},
    };
  }

  private async measureSelect(): Promise<unknown> {
    await this.ensureSurfaces();
    try { this.select.close(); } catch { /* closed */ }
    let notifications = 0;
    this.select.openedChange.subscribe(open => { if (open) notifications += 1; });
    this.select.open();
    await this.waitFor(() => !!document.querySelector('.mat-select-panel'));
    await this.wait(250);
    const el = document.querySelector('.mat-select-panel') as HTMLElement;
    const mode = this.mode();
    const observation = {
      selector: el.classList.contains('mat-select-panel') ? '.mat-select-panel' : '',
      selectorMatches: el.classList.contains('mat-select-panel') && !el.classList.contains('cdk-overlay-pane'),
      durationMs: this.duration(el, 'animation-duration'),
      finalState: this.visible(el) ? 'visible' : 'hidden',
      notifications,
      detectChangesCalls: 0,
    };
    this.select.close();
    await this.wait(300);
    return {
      key: `select/${mode}`,
      observation,
      notify: {key: `select/openedChange/${mode}`, observation: {notifications, detectChangesCalls: 0}},
    };
  }

  private async measureTooltip(): Promise<unknown> {
    await this.ensureSurfaces();
    this.tip.show(0);
    await this.wait(350);
    const el = document.querySelector('.mat-tooltip') as HTMLElement | null;
    const mode = this.mode();
    const observation = {
      selector: el && el.classList.contains('mat-tooltip') ? '.mat-tooltip' : '',
      selectorMatches: !!el && el.classList.contains('mat-tooltip') && !el.classList.contains('cdk-overlay-pane'),
      durationMs: el ? this.duration(el, 'animation-duration') : 0,
      finalState: this.visible(el) ? 'visible' : 'hidden',
      notifications: 0,
      detectChangesCalls: 0,
    };
    this.tip.hide(0);
    await this.wait(150);
    return {key: `tooltip/${mode}`, observation};
  }

  private clickTab(label: string): void {
    const labels = Array.from(document.querySelectorAll('.mat-tab-label-content'));
    const node = labels.find(item => (item.textContent || '').trim() === label);
    const labelHost = node ? node.closest('.mat-tab-label') as HTMLElement | null : null;
    if (!labelHost) throw new Error(`tab label ${label} missing`);
    labelHost.click();
  }

  private async measureTabs(zero: boolean): Promise<unknown> {
    await this.ensureSurfaces();
    this.tabDuration = zero ? '0ms' : '500ms';
    this.clickTab('One');
    await this.waitFor(() => {
      const node = document.querySelector('.mat-tab-body-active .mat-tab-body-content');
      return !!node && (node.textContent || '').includes('One') &&
        getComputedStyle(node).visibility !== 'hidden' && !document.querySelector('.mat-tab-body-animating');
    }, 1500);
    // The historical centered output is asynchronous. Flush the initial selection before observing.
    await this.wait(20);
    let notifications = 0;
    const sub = this.tabs.animationDone.subscribe(() => { notifications += 1; });
    try {
      this.clickTab('Two');
      const limit = zero || this.mode() !== 'enabled' ? 500 : 1500;
      await this.waitFor(() => {
        const node = document.querySelector('.mat-tab-body-active .mat-tab-body-content');
        return !!node && (node.textContent || '').includes('Two') &&
          getComputedStyle(node).visibility !== 'hidden' &&
          !document.querySelector('.mat-tab-body-animating') && notifications > 0;
      }, limit);
      const el = document.querySelector('.mat-tab-body-active .mat-tab-body-content') as HTMLElement | null;
      // Duplicate native completion events after settling must not produce a second group output.
      for (let i = 0; i < 2; i++) el?.dispatchEvent(new TransitionEvent('transitionend', {
        bubbles: true, propertyName: 'transform',
      }));
      await this.wait(20);
      const mode = zero ? 'zero' : this.mode();
      const observation = {
        selector: el && el.classList.contains('mat-tab-body-content') ? '.mat-tab-body-content' : '',
        selectorMatches: !!el && el.classList.contains('mat-tab-body-content'),
        durationMs: el ? this.duration(el, 'transition-duration') : 0,
        finalState: el && (el.textContent || '').includes('Two') && getComputedStyle(el).visibility !== 'hidden' ? 'visible' : 'hidden',
        notifications,
        duplicateEndEventsDispatched: !!el,
        detectChangesCalls: 0,
      };
      return {key: `tabs/${mode}`, observation, notify: {key: `tabs/animationDone/${mode}`, observation}};
    } finally {
      sub.unsubscribe();
      this.tabs.selectedIndex = 0;
      this.tabDuration = '500ms';
    }
  }

  private async measureField(): Promise<unknown> {
    await this.ensureSurfaces();
    this.name.setErrors({required: true});
    this.name.markAsTouched();
    await this.waitFor(() => (document.querySelector('.mat-form-field-subscript-message')?.textContent || '').includes('Required'));
    await this.wait(this.mode() === 'enabled' ? 400 : 40);
    const el = document.querySelector('.mat-form-field-subscript-message') as HTMLElement;
    const mode = this.mode();
    const text = el.textContent || '';
    const observation = {
      selector: el.classList.contains('mat-form-field-subscript-message') ? '.mat-form-field-subscript-message' : '',
      selectorMatches: el.classList.contains('mat-form-field-subscript-message') && !!el.closest('mat-form-field'),
      durationMs: this.duration(el, 'transition-duration'),
      finalState: text.includes('Required') && this.visible(el) ? 'visible' : 'hidden',
      notifications: 0,
      detectChangesCalls: 0,
    };
    this.name.setErrors(null);
    return {key: `form-field/${mode}`, observation};
  }

  private async reversal(): Promise<unknown> {
    this.dialog.closeAll();
    let opened = 0;
    const ref = this.dialog.open(DialogBody);
    ref.afterOpened().subscribe(() => { opened += 1; });
    ref.close();
    await this.wait(500);
    return {
      key: 'dialog/rapid-reversal',
      observation: {
        containers: document.querySelectorAll('mat-dialog-container').length,
        openedAfterClose: opened,
        leaks: document.querySelectorAll('mat-dialog-container').length,
        detectChangesCalls: 0,
      },
    };
  }

  private async reopen(): Promise<unknown> {
    this.dialog.closeAll();
    const first = this.dialog.open(DialogBody);
    await this.waitFor(() => !!document.querySelector('mat-dialog-container'));
    const firstEl = document.querySelector('mat-dialog-container') as HTMLElement;
    firstEl.setAttribute('data-motion-instance', 'first');
    first.close();
    await this.waitFor(() => !document.querySelector('mat-dialog-container'), 800);
    const second = this.dialog.open(DialogBody);
    await this.waitFor(() => !!document.querySelector('mat-dialog-container'));
    const secondEl = document.querySelector('mat-dialog-container') as HTMLElement;
    const secondInstance = secondEl.getAttribute('data-motion-instance') !== 'first';
    first.close();
    await this.wait(200);
    const still = document.querySelector('mat-dialog-container');
    const observation = {
      secondInstance,
      staleClosed: !still,
      leaks: document.querySelectorAll('mat-dialog-container').length === 1 ? 0 : document.querySelectorAll('mat-dialog-container').length,
      detectChangesCalls: 0,
    };
    second.close();
    return {key: 'dialog/reopen-instance', observation};
  }

  private async destroyDialog(): Promise<unknown> {
    const ref = this.dialog.open(DialogBody);
    await this.waitFor(() => !!document.querySelector('mat-dialog-container'));
    ref.close();
    this.dialog.closeAll();
    await this.wait(500);
    const containers = document.querySelectorAll('mat-dialog-container').length;
    return {key: 'dialog/destroy-cleanup', observation: {containers, leaks: containers, detectChangesCalls: 0}};
  }

  private async snackInterrupt(): Promise<unknown> {
    let notifications = 0;
    const ref = this.snack.open('Saved', 'OK', {duration: 30000});
    ref.afterOpened().subscribe(() => { notifications += 1; });
    await this.waitFor(() => !!document.querySelector('snack-bar-container'));
    const host = document.querySelector('snack-bar-container') as HTMLElement;
    const child = host.firstElementChild as HTMLElement;
    child.dispatchEvent(new AnimationEvent('animationend', {animationName: 'mat-legacy-snack-bar-enter', bubbles: true}));
    await this.wait(40);
    const descendantIgnored = notifications === 0;
    host.style.setProperty('animation', 'none');
    await this.waitFor(() => notifications >= 1, 800);
    const observation = {descendantIgnored, completions: notifications, detectChangesCalls: 0};
    ref.dismiss();
    await this.wait(200);
    return {
      results: {
        'snack-bar/descendant-end': observation,
        'snack-bar/fallback-without-end-event': {
          endEventDispatched: false,
          fallbackCompleted: notifications === 1,
          completions: notifications,
          detectChangesCalls: 0,
        },
      },
    };
  }

  private async menuDuplicate(): Promise<unknown> {
    await this.ensureSurfaces();
    let completions = 0;
    const sub = this.menu._animationDone.subscribe(() => { completions += 1; });
    this.menuTrigger.openMenu();
    await this.waitFor(() => !!document.querySelector('.mat-menu-panel'));
    const panel = document.querySelector('.mat-menu-panel') as HTMLElement;
    const event = () => panel.dispatchEvent(new AnimationEvent('animationend', {animationName: 'mat-legacy-menu-enter', bubbles: true}));
    event();
    event();
    await this.wait(200);
    sub.unsubscribe();
    this.menuTrigger.closeMenu();
    return {key: 'menu/duplicate-end', observation: {duplicateDispatched: true, completions, detectChangesCalls: 0}};
  }

  private async menuDescendant(): Promise<unknown> {
    await this.ensureSurfaces();
    let completions = 0;
    const sub = this.menu._animationDone.subscribe(() => { completions += 1; });
    this.menuTrigger.openMenu();
    await this.waitFor(() => !!document.querySelector('.mat-menu-panel'));
    const panel = document.querySelector('.mat-menu-panel') as HTMLElement;
    const child = panel.querySelector('button') as HTMLElement;
    child.dispatchEvent(new AnimationEvent('animationend', {animationName: 'mat-legacy-menu-enter', bubbles: true}));
    await this.wait(30);
    const descendantIgnored = completions === 0;
    panel.dispatchEvent(new AnimationEvent('animationend', {animationName: 'mat-legacy-menu-enter', bubbles: true}));
    await this.wait(80);
    sub.unsubscribe();
    this.menuTrigger.closeMenu();
    return {key: 'menu/descendant-end', observation: {descendantIgnored, completions, detectChangesCalls: 0}};
  }

  private async selectDescendant(): Promise<unknown> {
    await this.ensureSurfaces();
    let completions = 0;
    const sub = this.select._panelDoneAnimatingStream.subscribe(() => { completions += 1; });
    this.select.open();
    await this.waitFor(() => !!document.querySelector('.mat-select-panel'));
    const panel = document.querySelector('.mat-select-panel') as HTMLElement;
    const option = panel.querySelector('mat-option') as HTMLElement;
    option.dispatchEvent(new AnimationEvent('animationend', {animationName: 'mat-legacy-select-enter', bubbles: true}));
    await this.wait(40);
    const panelRemained = !!document.querySelector('.mat-select-panel');
    const descendantIgnored = completions === 0 && panelRemained;
    sub.unsubscribe();
    this.select.close();
    await this.wait(300);
    return {key: 'select/descendant-end', observation: {descendantIgnored, panelRemained, detectChangesCalls: 0}};
  }

  private async selectFallback(): Promise<unknown> {
    await this.ensureSurfaces();
    let touchedReopens = 0;
    this.select.registerOnTouched(() => {
      touchedReopens++;
      this.select.open();
      return {};
    });
    this.select.open();
    await this.waitFor(() => !!document.querySelector('.mat-select-panel'));
    this.select.close();
    await this.wait(300);
    const reopenedPanelVisible = this.select.panelOpen &&
      this.visible(document.querySelector('.mat-select-panel') as HTMLElement | null);
    this.select.registerOnTouched(() => ({}));
    this.select.close();
    await this.wait(300);
    this.select.open();
    await this.waitFor(() => !!document.querySelector('.mat-select-panel'));
    this.select.close();
    const panel = document.querySelector('.mat-select-panel') as HTMLElement | null;
    if (panel) panel.style.setProperty('animation', 'none');
    await this.wait(450);
    const gone = !document.querySelector('.mat-select-panel');
    return {key: 'select/missing-end-fallback', observation: {
      endEventDispatched: false, fallbackCompleted: gone,
      touchedReopens, reopenedPanelVisible, detectChangesCalls: 0,
    }};
  }

  private async tooltipDestroy(): Promise<unknown> {
    await this.ensureSurfaces();
    this.showGone = true;
    await this.wait(20);
    if (!this.tipGone) throw new Error('tooltip host missing');
    this.tipGone.show(0);
    await this.wait(120);
    const shown = !!document.querySelector('.mat-tooltip');
    document.getElementById('remove-gone')!.click();
    await this.wait(200);
    const leaks = document.querySelectorAll('.mat-tooltip').length;
    return {key: 'tooltip/destroy-while-shown', observation: {destroyed: shown && leaks === 0, leaks, detectChangesCalls: 0}};
  }

  private async tabsRapid(): Promise<unknown> {
    await this.ensureSurfaces();
    this.tabDuration = '500ms';
    this.clickTab('One');
    await this.wait(40);
    const el = document.querySelector('.mat-tab-body-content') as HTMLElement;
    const durationMs = this.duration(el, 'transition-duration');
    this.clickTab('Two');
    this.clickTab('Three');
    await this.waitFor(() => {
      const node = document.querySelector('.mat-tab-body-active .mat-tab-body-content');
      const text = node ? node.textContent || '' : '';
      return text.includes('Three') && !document.querySelector('.mat-tab-body-animating');
    }, 1500);
    const active = document.querySelector('.mat-tab-body-active .mat-tab-body-content');
    const text = active ? active.textContent || '' : '';
    return {
      key: 'tabs/rapid-reversal',
      observation: {
        durationMs,
        finalState: text.includes('Three') ? 'visible' : 'hidden',
        animating: !!document.querySelector('.mat-tab-body-animating'),
        detectChangesCalls: 0,
      },
    };
  }
}

@NgModule({
  imports: [
    BrowserModule,
    ReactiveFormsModule,
    MatLegacyDialogModule,
    MatLegacyFormFieldModule,
    MatLegacyInputModule,
    MatLegacyMenuModule,
    MatLegacySelectModule,
    MatLegacySnackBarModule,
    MatLegacyTabsModule,
    MatLegacyTooltipModule,
  ],
  declarations: [MotionRoot, DialogBody],
  bootstrap: [MotionRoot],
  providers: [/*ZONE_PROVIDER*/...motionProviders],
})
export class MotionModule {}

platformBrowserDynamic().bootstrapModule(MotionModule).catch(err => {
  const node = document.createElement('pre');
  node.id = 'bootstrap-error';
  node.textContent = String(err);
  document.body.appendChild(node);
});

#!/usr/bin/env node
/**
 * 21.x native-motion roster.
 *
 * Ids are derived from the components that own native CSS/timer motion
 * before any browser launches. WebKitGTK is the webkit engine. It is not
 * Safari. Main is not part of this roster. motion-smoke stays a separate
 * source check.
 */
import {readFileSync, writeFileSync} from 'node:fs';
import {dirname, join, resolve} from 'node:path';
import {fileURLToPath} from 'node:url';
import {engineIdentityProblems} from './browser-matrix-roster.mjs';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');

export const SOURCE_LINE = '21.x';

export const ENGINES = ['chromium', 'firefox', 'webkit'];
export const RUNTIMES = ['zoneful', 'zoneless'];
export const COMPONENTS = ['dialog', 'snack-bar', 'menu', 'select', 'tooltip', 'tabs', 'form-field'];
export const MODES = ['enabled', 'provider-disabled', 'reduced'];
export const ZERO_COMPONENTS = ['dialog', 'tabs'];
export const NOTIFY = [
  ['dialog', 'afterOpened', ['enabled', 'provider-disabled', 'reduced', 'zero']],
  ['snack-bar', 'afterOpened', ['enabled', 'provider-disabled', 'reduced']],
  ['menu', 'menuOpened', ['enabled', 'provider-disabled', 'reduced']],
  ['select', 'openedChange', ['enabled', 'provider-disabled', 'reduced']],
  ['tabs', 'animationDone', ['enabled', 'provider-disabled', 'reduced', 'zero']],
];
export const INTERRUPTIONS = [
  'dialog/rapid-reversal',
  'dialog/reopen-instance',
  'dialog/destroy-cleanup',
  'snack-bar/descendant-end',
  'snack-bar/fallback-without-end-event',
  'menu/duplicate-end',
  'menu/descendant-end',
  'select/descendant-end',
  'select/missing-end-fallback',
  'tooltip/destroy-while-shown',
  'tabs/rapid-reversal',
];
export const SELECTORS = {
  dialog: 'mat-dialog-container',
  'snack-bar': 'snack-bar-container',
  menu: '.mat-menu-panel',
  select: '.mat-select-panel',
  tooltip: '.mat-tooltip',
  tabs: '.mat-tab-body-content',
  'form-field': '.mat-form-field-subscript-message',
};
export const MIN_ENABLED_MS = {
  dialog: 100,
  'snack-bar': 100,
  menu: 50,
  select: 50,
  tooltip: 100,
  tabs: 400,
  'form-field': 200,
};
const NOTIFICATION_CONTRACT = new Set(['dialog', 'snack-bar', 'menu', 'select', 'tabs']);

export const MODE_BUTTONS = [
  'probe-dialog',
  'probe-snack',
  'probe-menu',
  'probe-select',
  'probe-tooltip',
  'probe-tabs',
  'probe-field',
];
export const ZERO_BUTTONS = ['probe-dialog-zero', 'probe-tabs-zero'];
export const INTERRUPT_BUTTONS = [
  'interrupt-dialog-reversal',
  'interrupt-dialog-reopen',
  'interrupt-dialog-destroy',
  'interrupt-snack',
  'interrupt-menu-duplicate',
  'interrupt-menu-descendant',
  'interrupt-select-descendant',
  'interrupt-select-fallback',
  'interrupt-tooltip-destroy',
  'interrupt-tabs',
];

export const NOT_APPLICABLE = [
  {component: 'snack-bar', mode: 'zero', reason: 'no public animation-duration input; a stylesheet 0ms override would be a fake'},
  {component: 'menu', mode: 'zero', reason: 'no public animation-duration input; a stylesheet 0ms override would be a fake'},
  {component: 'select', mode: 'zero', reason: 'no public animation-duration input; a stylesheet 0ms override would be a fake'},
  {component: 'tooltip', mode: 'zero', reason: 'no public animation-duration input; showDelay is not component motion'},
  {component: 'form-field', mode: 'zero', reason: 'subscript motion has no public duration input; a stylesheet 0ms override would be a fake'},
  {component: 'tooltip', group: 'exactly-once-notification', reason: 'no public completion event; visibility stays in enabled-disabled-reduced'},
  {component: 'form-field', group: 'exactly-once-notification', reason: 'subscript motion has no public completion event'},
  {component: 'form-field', group: 'interruption-destruction', reason: 'subscript motion has no overlay, timer fallback, or end-event lifecycle'},
  {engine: 'safari', reason: 'the card names the webkit engine, not Safari; WebKitGTK is that engine and is not Safari certification'},
];

function id(engine, runtime, group, suffix) {
  return `native-motion/${SOURCE_LINE}/${engine}/${runtime}/${group}/${suffix}`;
}

export function buttonsFor(scene, mode) {
  if (scene === 'interrupt') return INTERRUPT_BUTTONS;
  if (mode === 'enabled') return [...MODE_BUTTONS, ...ZERO_BUTTONS];
  if (MODES.includes(mode)) return MODE_BUTTONS;
  throw new Error(`unknown motion scene ${scene}/${mode}`);
}

export function deriveMainRoster() {
  const enabled = [];
  for (const component of COMPONENTS) {
    const modes = ZERO_COMPONENTS.includes(component) ? [...MODES, 'zero'] : MODES;
    for (const mode of modes) {
      for (const runtime of RUNTIMES) {
        for (const engine of ENGINES) {
          enabled.push(id(engine, runtime, 'enabled-disabled-reduced', `${component}/${mode}`));
        }
      }
    }
  }
  const interrupt = [];
  for (const suffix of INTERRUPTIONS) {
    for (const runtime of RUNTIMES) {
      for (const engine of ENGINES) interrupt.push(id(engine, runtime, 'interruption-destruction', suffix));
    }
  }
  const notify = [];
  for (const [component, event, modes] of NOTIFY) {
    for (const mode of modes) {
      for (const runtime of RUNTIMES) {
        for (const engine of ENGINES) {
          notify.push(id(engine, runtime, 'exactly-once-notification', `${component}/${event}/${mode}`));
        }
      }
    }
  }
  const groups = {
    'enabled-disabled-reduced': enabled,
    'interruption-destruction': interrupt,
    'exactly-once-notification': notify,
  };
  const ids = [...enabled, ...interrupt, ...notify];
  if (new Set(ids).size !== ids.length) throw new Error('duplicate native-motion id');
  const perEngine = {};
  for (const engine of ENGINES) perEngine[engine] = ids.filter(item => item.split('/')[2] === engine).length;
  const perGroup = {};
  for (const [name, list] of Object.entries(groups)) perGroup[name] = list.length;
  return {ids, groups, perEngine, perGroup, engines: ENGINES, notApplicable: NOT_APPLICABLE};
}

function enabledProblem(component, mode, obs) {
  if (!obs || typeof obs !== 'object') return 'missing observation';
  if (obs.detectChangesCalls !== 0) return 'detectChanges stand-in';
  if (obs.selector !== SELECTORS[component] || obs.selectorMatches !== true) return 'wrapper background is not component motion';
  if (obs.finalState !== 'visible') return 'missing final state';
  if (mode === 'enabled') {
    if (!(typeof obs.durationMs === 'number' && obs.durationMs >= MIN_ENABLED_MS[component])) return 'zero-duration CSS fake';
  } else if (obs.durationMs !== 0) {
    return 'disabled motion still running';
  }
  if (component === 'tabs' && obs.duplicateEndEventsDispatched !== true) return 'tab duplicate completion control missing';
  if (NOTIFICATION_CONTRACT.has(component) && obs.notifications !== 1) return 'notification count';
  return null;
}

function interruptProblem(suffix, obs) {
  if (!obs || typeof obs !== 'object') return 'missing observation';
  if (obs.detectChangesCalls !== 0) return 'detectChanges stand-in';
  if (suffix === 'dialog/rapid-reversal') {
    if (obs.containers !== 0 || obs.leaks !== 0) return 'timer or overlay leak';
    if (obs.openedAfterClose !== 0) return 'stale open notification';
    return null;
  }
  if (suffix === 'dialog/reopen-instance') {
    if (obs.staleClosed === true) return 'stale close removed the reopened instance';
    if (obs.secondInstance !== true || obs.leaks !== 0) return 'reopened instance was not a new container';
    return null;
  }
  if (suffix === 'dialog/destroy-cleanup') {
    if (obs.containers !== 0 || obs.leaks !== 0) return 'timer or overlay leak';
    return null;
  }
  if (suffix === 'snack-bar/descendant-end' || suffix === 'menu/descendant-end') {
    if (obs.descendantIgnored !== true) return 'descendant event counted as completion';
    if (obs.completions !== 1) return 'emitted more than once';
    return null;
  }
  if (suffix === 'snack-bar/fallback-without-end-event') {
    if (obs.endEventDispatched !== false) return 'fallback was not isolated from an end event';
    if (obs.fallbackCompleted !== true || obs.completions !== 1) return 'missing fallback completion';
    return null;
  }
  if (suffix === 'menu/duplicate-end') {
    if (obs.duplicateDispatched !== true) return 'duplicate end event was not sent';
    if (obs.completions !== 1) return 'emitted more than once';
    return null;
  }
  if (suffix === 'select/descendant-end') {
    if (obs.descendantIgnored !== true) return 'descendant event counted as completion';
    if (obs.panelRemained !== true) return 'descendant event destroyed the panel';
    return null;
  }
  if (suffix === 'select/missing-end-fallback') {
    if (obs.endEventDispatched !== false) return 'fallback was not isolated from an end event';
    if (obs.fallbackCompleted !== true) return 'missing fallback completion';
    if (obs.touchedReopens !== 1 || obs.reopenedPanelVisible !== true) return 'touched callback closed the reopened panel';
    return null;
  }
  if (suffix === 'tooltip/destroy-while-shown') {
    if (obs.destroyed !== true || obs.leaks !== 0) return 'timer or overlay leak';
    return null;
  }
  if (suffix === 'tabs/rapid-reversal') {
    if (!(typeof obs.durationMs === 'number' && obs.durationMs >= MIN_ENABLED_MS.tabs)) return 'zero-duration CSS fake';
    if (obs.finalState !== 'visible' || obs.animating !== false) return 'rapid reversal did not settle on the last tab';
    return null;
  }
  return 'unknown interruption';
}

export function assertCase(caseId, obs) {
  const parts = String(caseId || '').split('/');
  if (parts.length < 6 || parts[0] !== 'native-motion' || parts[1] !== SOURCE_LINE) return ['unknown case'];
  const group = parts[4];
  const suffix = parts.slice(5).join('/');
  if (group === 'enabled-disabled-reduced') {
    const [component, mode] = suffix.split('/');
    const problem = enabledProblem(component, mode, obs);
    return problem ? [problem] : [];
  }
  if (group === 'interruption-destruction') {
    const problem = interruptProblem(suffix, obs);
    return problem ? [problem] : [];
  }
  if (group === 'exactly-once-notification') {
    if (!obs || typeof obs !== 'object') return ['missing observation'];
    if (obs.detectChangesCalls !== 0) return ['detectChanges stand-in'];
    if (suffix.startsWith('tabs/') && obs.duplicateEndEventsDispatched !== true) return ['tab duplicate completion control missing'];
    if (obs.notifications !== 1) return ['emitted more than once'];
    return [];
  }
  return ['unknown case'];
}

export function samplePass(caseId) {
  const parts = caseId.split('/');
  const group = parts[4];
  const suffix = parts.slice(5).join('/');
  if (group === 'enabled-disabled-reduced') {
    const [component, mode] = suffix.split('/');
    return {
      selector: SELECTORS[component],
      selectorMatches: true,
      durationMs: mode === 'enabled' ? MIN_ENABLED_MS[component] : 0,
      finalState: 'visible',
      notifications: NOTIFICATION_CONTRACT.has(component) ? 1 : 0,
      ...(component === 'tabs' ? {duplicateEndEventsDispatched: true} : {}),
      detectChangesCalls: 0,
    };
  }
  if (group === 'exactly-once-notification') return {notifications: 1, detectChangesCalls: 0, ...(suffix.startsWith('tabs/') ? {duplicateEndEventsDispatched: true} : {})};
  const base = {detectChangesCalls: 0};
  if (suffix === 'dialog/rapid-reversal') return {...base, containers: 0, leaks: 0, openedAfterClose: 0};
  if (suffix === 'dialog/reopen-instance') return {...base, secondInstance: true, staleClosed: false, leaks: 0};
  if (suffix === 'dialog/destroy-cleanup') return {...base, containers: 0, leaks: 0};
  if (suffix === 'snack-bar/descendant-end' || suffix === 'menu/descendant-end') return {...base, descendantIgnored: true, completions: 1};
  if (suffix === 'snack-bar/fallback-without-end-event') return {...base, endEventDispatched: false, fallbackCompleted: true, completions: 1};
  if (suffix === 'menu/duplicate-end') return {...base, duplicateDispatched: true, completions: 1};
  if (suffix === 'select/descendant-end') return {...base, descendantIgnored: true, panelRemained: true};
  if (suffix === 'select/missing-end-fallback') return {...base, endEventDispatched: false, fallbackCompleted: true, touchedReopens: 1, reopenedPanelVisible: true};
  if (suffix === 'tooltip/destroy-while-shown') return {...base, destroyed: true, leaks: 0};
  if (suffix === 'tabs/rapid-reversal') return {...base, durationMs: MIN_ENABLED_MS.tabs, finalState: 'visible', animating: false};
  return base;
}

export function observationProblems({requiredIds, outcomes, engines, sourceClean, artifactSha, boundSha}) {
  const problems = [];
  if (sourceClean !== true) problems.push('dirty source');
  if (!artifactSha || artifactSha !== boundSha) problems.push('unbound artifact');
  problems.push(...engineIdentityProblems(engines || {}));
  const passed = new Set();
  for (const row of outcomes || []) {
    if (!row || row.ok !== true) continue;
    const caseProblems = assertCase(row.id, row.observation);
    if (caseProblems.length) problems.push(...caseProblems.map(item => `${row.id}: ${item}`));
    else if (typeof row.evidence === 'string' && row.evidence.length > 0) passed.add(row.id);
  }
  const skipped = [];
  for (const caseId of requiredIds) {
    if (!passed.has(caseId)) skipped.push(caseId);
  }
  if (skipped.length) problems.push(`skipped required cell ${skipped[0]}`);
  return {problems, skipped};
}

function writeMatrix() {
  const roster = deriveMainRoster();
  const matrixPath = join(root, 'compatibility/rc/matrices/full-verify.json');
  const matrix = JSON.parse(readFileSync(matrixPath, 'utf8'));
  const row = matrix.checks.find(item => item.check_id === 'native-motion');
  row.implemented = true;
  row.acceptance.cases_by_line[SOURCE_LINE] = roster.groups;
  for (const group of Object.keys(roster.groups)) row.acceptance.cases_by_line['main'][group] = null;
  writeFileSync(matrixPath, `${JSON.stringify(matrix, null, 2)}\n`);
  console.log(`wrote native-motion ${SOURCE_LINE} roster ${roster.ids.length}`);
}

const entry = process.argv[1] ? resolve(process.argv[1]) : '';
if (entry === fileURLToPath(import.meta.url)) {
  if (process.argv.includes('--write-matrix')) writeMatrix();
  else {
    const roster = deriveMainRoster();
    console.log(JSON.stringify({cases: roster.ids.length, perEngine: roster.perEngine, perGroup: roster.perGroup}));
  }
}

#!/usr/bin/env node
/**
 * Packed-consumer AOT + harness runtime expansion beyond ESM import smoke.
 *
 * Creates a clean temp consumer, installs the packed tarball + aged Angular
 * peers, compiles strict declarations and separate consumer scopes, and runs
 * Angular TestBed DOM/harness contracts, including six actual legacy value
 * accessors. TestBed uses JSDOM; native browser qualification is separate.
 *
 * Usage:
 *   node scripts/packed-consumer-aot-smoke.mjs --tarball path [--skip-harness]
 * Evidence:
 *   compatibility/pack-proof/aot-harness-smoke.json
 */
import {npmToolingOptions} from './npm-tooling-options.mjs';
import {
  cpSync,
  existsSync,
  lstatSync,
  mkdirSync,
  mkdtempSync,
  readdirSync,
  readFileSync,
  realpathSync,
  rmSync,
  statSync,
  writeFileSync,
} from 'node:fs';
import {createHash} from 'node:crypto';
import {tmpdir} from 'node:os';
import {dirname, isAbsolute, join, relative, resolve, sep} from 'node:path';
import {fileURLToPath} from 'node:url';
import {spawnSync} from 'node:child_process';
import {floorConfigurations,candidateFloorConfigurations} from './consumer-floor-roster.mjs';
import {bundleConsumerHarness} from './bundle-consumer-harness.mjs';
import {valueAccessorPackedFixture} from './value-accessor-packed-fixture.mjs';
import {packedValueAccessorCases} from './value-accessor-packed-contract.mjs';
import {assertEngineFreeConsumer, assertEngineFreeHarnessInputs} from './consumer-animation-engine.mjs';
import {
  allConsumerCaseIds,
  coordinatorRequest,
  declarationKeys,
  declarationObservations,
  harnessCaseIds,
  librarySpec as packagedSpec,
  lineForPackageVersion,
  loadExportKeys,
  projectFacts,
  readPackedIdentity,
  writeAcceptanceReport,
} from './packed-consumer-evidence.mjs';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const outPath = join(root, 'compatibility/pack-proof/aot-harness-smoke.json');
// F00: committed historical tarball moved to pack-proof/historical-unbound/.
// Do not silently default to it. F01 will wire fresh build/pack → --tarball.
const historicalUnboundTarball = join(
  root,
  'compatibility/pack-proof/historical-unbound/ngx-compat-material-legacy-22.0.0-rc.0.tgz',
);

const args = process.argv.slice(2);
const skipHarness = args.includes('--skip-harness');
let tarball = null;
let runManifestPath = null;
let floorCaseId = null;
let candidateFloor = false;
let floorOutput = null;

for (let i = 0; i < args.length; i += 1) {
  const arg = args[i];
  if (arg === '--skip-harness') continue;
  if (arg === '--tarball' || arg === '--run' || arg === '--floor-case' || arg === '--candidate-floor-case' || arg === '--floor-out') {
    const value = args[i + 1];
    if (!value || value.startsWith('-')) {
      console.error(`${arg} requires a path`);
      process.exit(2);
    }
    if (arg === '--tarball') tarball = resolve(value);
    else if (arg === '--run') runManifestPath = resolve(value);
    else if (arg === '--floor-case' || arg === '--candidate-floor-case') {
      if (floorCaseId) {console.error('Duplicate floor mode');process.exit(2);}
      floorCaseId = value;candidateFloor = arg === '--candidate-floor-case';
    }
    else floorOutput = resolve(value);
    i += 1;
    continue;
  }
  console.error(`Unknown argument: ${arg}`);
  process.exit(2);
}

const coordinator = coordinatorRequest('packed-consumer');
if (coordinator && coordinator.error) {
  console.error(`packed-consumer: refusing acceptance report: ${coordinator.error}`);
  process.exit(2);
}
const exportKeys = loadExportKeys();
console.log(`packed-consumer: derived ${allConsumerCaseIds(exportKeys).length} cases before reading the candidate`);

function sha256File(path) {
  return createHash('sha256').update(readFileSync(path)).digest('hex');
}

function insideDir(dir, target) {
  const rel = relative(resolve(dir), resolve(target));
  return rel === '' || (!rel.startsWith('..') && !isAbsolute(rel));
}

function run(cmd, cmdlineArgs, opts = {}) {
  if (floorCaseId && cmd === 'npm') {
    const npmCli = process.env.NGX_FLOOR_NPM_CLI;
    if (!npmCli || !isAbsolute(npmCli) || !npmCli.endsWith('/npm-cli.js')) throw new Error('qualified floor npm CLI required');
    cmd = process.execPath;
    cmdlineArgs = [npmCli, ...cmdlineArgs];
  }
  const res = spawnSync(cmd, cmdlineArgs, {
    encoding: 'utf8',
    ...opts,
  });
  return res;
}

function isolatedEnv() {
  const env = {...process.env, NODE_OPTIONS: ''};
  delete env.NODE_PATH;
  return env;
}

function isInside(parent, target) {
  const rel = relative(parent, target);
  return rel === '' || (!rel.startsWith('..') && !isAbsolute(rel));
}

function librarySpec(exportKey) {
  return packagedSpec(exportKey);
}

function compilePeerHarness(consumer, rootReal) {
  const legacySpec = '@ngx-compat/material-legacy/legacy-button/testing';
  const peerSpec = '@angular/material/button/testing';
  writeFileSync(
    join(consumer, 'src/peer-harness.ts'),
    "import {MatButtonHarness} from '@angular/material/button/testing';\nexport const peerHarness = MatButtonHarness;\n",
  );
  const config = {
    compilerOptions: {
      target: 'ES2022',
      module: 'ES2022',
      moduleResolution: 'bundler',
      strict: true,
      skipLibCheck: false,
      noEmit: true,
      experimentalDecorators: true,
      lib: ['ES2022', 'DOM'],
      types: [],
    },
    files: ['src/peer-harness.ts'],
  };
  writeFileSync(join(consumer, 'tsconfig.peer-harness.json'), JSON.stringify(config, null, 2));
  const compiled = run(
    process.execPath,
    [join(consumer, 'node_modules/typescript/lib/tsc.js'), '-p', 'tsconfig.peer-harness.json', '--pretty', 'false'],
    {cwd: consumer, timeout: 180000, env: isolatedEnv()},
  );
  const resolveSpec = spec => {
    const probe = run(
      process.execPath,
      ['--input-type=module', '-e', `
        import {createRequire} from 'node:module';
        import {pathToFileURL} from 'node:url';
        const require = createRequire(pathToFileURL(process.cwd() + '/'));
        console.log(require.resolve(process.env.LEGACY_SPEC));
      `],
      {cwd: consumer, env: {...isolatedEnv(), LEGACY_SPEC: spec}},
    );
    if (probe.status !== 0) return null;
    return realpathSync(probe.stdout.trim());
  };
  const legacyPath = resolveSpec(legacySpec);
  const peerPath = resolveSpec(peerSpec);
  const legacyOwned = Boolean(legacyPath && legacyPath.includes(`${sep}@ngx-compat${sep}material-legacy${sep}`) && !isInside(rootReal, legacyPath));
  const peerOwned = Boolean(peerPath && peerPath.includes(`${sep}@angular${sep}material${sep}`) && !legacyPath?.startsWith(peerPath) && peerPath !== legacyPath);
  const ok = compiled.status === 0 && legacyOwned && peerOwned;
  return {
    ok,
    exit_code: compiled.status,
    legacy_path: legacyPath,
    peer_path: peerPath,
    failure: ok ? null : `peer/owned harness scope failed\n${(compiled.stdout || '').slice(-800)}\n${(compiled.stderr || '').slice(-800)}`,
  };
}

function assertIsolatedInstall(consumer, consumerReal, rootReal) {
  const animationEngine = assertEngineFreeConsumer(consumer);
  const pkgRoot = join(consumer, 'node_modules/@ngx-compat/material-legacy');
  const pkgReal = realpathSync(pkgRoot);
  if (
    isInside(rootReal, pkgReal) ||
    pkgReal.includes(`${sep}projects${sep}ngx-material-legacy`) ||
    pkgReal.includes(`${sep}dist${sep}ngx-material-legacy`)
  ) {
    throw new Error(`Installed library resolves inside the workspace: ${pkgReal}`);
  }
  if (!isInside(consumerReal, pkgReal)) {
    throw new Error(`Installed library is outside the consumer install: ${pkgReal}`);
  }

  const workspaceLinks = [];
  const modulesDir = join(consumer, 'node_modules');
  for (const entry of readdirSync(modulesDir)) {
    const entryPath = join(modulesDir, entry);
    const children = entry.startsWith('@') && !entry.startsWith('.')
      ? readdirSync(entryPath).map(name => join(entryPath, name))
      : [entryPath];
    for (const child of children) {
      if (!lstatSync(child).isSymbolicLink()) continue;
      const target = realpathSync(child);
      if (isInside(rootReal, target)) workspaceLinks.push(`${child} -> ${target}`);
    }
  }
  if (workspaceLinks.length) {
    throw new Error(`Consumer links into the repository: ${workspaceLinks.join(', ')}`);
  }

  const installed = JSON.parse(readFileSync(join(pkgRoot, 'package.json'), 'utf8'));
  const specs = Object.entries(installed.exports ?? {})
    .filter(([key, value]) => {
      if (key === './_index' || key === './package.json') return false;
      return Boolean(value && (value.default || value.import || value.types));
    })
    .map(([key]) => librarySpec(key));
  const resolved = [];
  for (const spec of specs) {
    const probe = run(
      process.execPath,
      ['--input-type=module', '-e', `
        import {createRequire} from 'node:module';
        import {pathToFileURL} from 'node:url';
        const require = createRequire(pathToFileURL(process.cwd() + '/'));
        console.log(require.resolve(process.env.LEGACY_SPEC));
      `],
      {cwd: consumer, env: {...isolatedEnv(), LEGACY_SPEC: spec}},
    );
    if (probe.status !== 0) {
      throw new Error(`Unable to resolve ${spec}: ${(probe.stderr || probe.stdout || '').slice(-500)}`);
    }
    const found = realpathSync(probe.stdout.trim());
    if (
      isInside(rootReal, found) ||
      !found.includes(`${sep}@ngx-compat${sep}material-legacy${sep}`)
    ) {
      throw new Error(`${spec} resolved outside the installed library: ${found}`);
    }
    resolved.push({spec, path: found, insideWorkspace: isInside(rootReal, found), insideConsumer: isInside(consumerReal, found)});
  }

  const animationHits = [];
  for (const name of readdirSync(join(pkgRoot, 'fesm2022'))) {
    if (!name.endsWith('.mjs')) continue;
    const text = readFileSync(join(pkgRoot, 'fesm2022', name), 'utf8');
    if (
      /from\s+['"]@angular\/animations['"]/.test(text) ||
      /require\(\s*['"]@angular\/animations['"]\s*\)/.test(text)
    ) {
      animationHits.push(name);
    }
  }
  if (animationHits.length) {
    throw new Error(`Installed library imports @angular/animations: ${animationHits.join(', ')}`);
  }

  const lock = JSON.parse(readFileSync(join(consumer, 'package-lock.json'), 'utf8'));
  const lockedCore = lock.packages?.['node_modules/@angular/core']?.version;
  if (lockedCore !== '21.2.23') {
    throw new Error(`Consumer lock resolved @angular/core@${lockedCore ?? 'missing'}, expected 21.2.23`);
  }

  mkdirSync(join(consumer, 'src'), {recursive: true});
  writeFileSync(
    join(consumer, 'src/all-entries.ts'),
    `${specs.map(spec => `import '${spec}';`).join('\n')}\nexport {};\n`,
  );
  writeFileSync(
    join(consumer, 'tsconfig.entries.json'),
    JSON.stringify(
      {
        compilerOptions: {
          target: 'ES2022',
          module: 'ES2022',
          moduleResolution: 'bundler',
          strict: true,
          skipLibCheck: false,
          noEmit: true,
          experimentalDecorators: true,
          lib: ['ES2022', 'DOM'],
          types: [],
        },
        files: ['src/all-entries.ts'],
      },
      null,
      2,
    ),
  );
  const tsc = run(
    process.execPath,
    [join(consumer, 'node_modules/typescript/lib/tsc.js'), '-p', 'tsconfig.entries.json', '--pretty', 'false'],
    {cwd: consumer, timeout: 180000, env: isolatedEnv()},
  );
  if (tsc.status !== 0) {
    throw new Error(
