  );
  const tsc = run(
    process.execPath,
    [join(consumer, 'node_modules/typescript/lib/tsc.js'), '-p', 'tsconfig.entries.json', '--pretty', 'false'],
    {cwd: consumer, timeout: 180000, env: isolatedEnv()},
