export class LegacyStrictModule {}
`,
  );
  writeFileSync(
    join(consumer, 'src/modern-strict.ts'),
    `import {Component, NgModule} from '@angular/core';
import {MatButtonModule} from '@angular/material/button';

@Component({
  standalone: false,
