export class ModernStrictModule {}
`,
  );
  const strictConfig = (file, outDir) => ({
    compilerOptions: {
      target: 'ES2022',
      module: 'ES2022',
      moduleResolution: 'bundler',
      experimentalDecorators: true,
      strict: true,
      skipLibCheck: false,
