  return {
    consumer_outside_repository: true,
    node_path: 'unset',
    workspace_symlinks: [],
    resolved,
    resolved_entries: resolved.length,
    declaration_program_ok: true,
    projects,
    declaration_check: 'skipLibCheck:false',
    strict_templates: ['legacy-button', 'modern-button'],
