      }else{
        await Promise.race([
          Promise.allSettled([document.fonts.ready,...running.map(animation=>animation.finished)]),
          new Promise(resolve=>setTimeout(resolve,Math.min(50,Math.max(1,deadline-performance.now())))),
        ]);
      }
    }
  })()`);
}

